import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type ValuationAnimationProps = Record<string, any>;

const ValuationAnimation: React.FC<ValuationAnimationProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 15,
  mainTitle = "Running your valuation engine...",
  subTitle = "Running all 6 valuation engines -- DCF, Comps, Precedent, Bottom-Up, Asset Floor & more...",
  tasksCardHeader = "Running your valuation",
  timerMaxSeconds = 1.6,
  tasks = [
    "Ingesting financial statements",
    "Normalizing line items",
    "Computing trailing revenue & EBITDA",
    "Fetching treasury + ERP + beta",
    "Solving industry-weighted WACC",
    "Projecting 10-year free cash flow",
    "Computing DCF terminal value",
    "Screening public comparable companies",
    "Filtering comps by size + geography",
    "Computing median EV/Revenue + EV/EBITDA"
  ],
  timeToValueHeader = "TIME TO VALUE",
  gaugeTime = "3m 16s",
  oldTimeText = "4 - 6 WEEKS",
  newTimeText = "3M 16S",
  multiplierText = "3,700x FASTER"
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Scale to fit screen
  const s = Math.min(width / 1920, height / 1080);
  const containerBg = transparentBackground ? "transparent" : backgroundColor;

  // Timeline Calculations
  const durationInFrames = Math.round(durationInSeconds * fps);
  const fadeDur = Math.max(1, Math.min(fps, Math.round(durationInFrames * 0.05)));
  
  // Phase 1: Tasks
  const t_topFadeStart = 0;
  const t_taskCardStart = Math.max(1, Math.round(durationInFrames * 0.05));
  const t_taskProgressStart = Math.max(2, Math.round(durationInFrames * 0.1));
  const t_taskProgressEnd = Math.round(durationInFrames * 0.55);

  // Phase 2: Blackout Transition
  const t_blackOutStart = Math.round(durationInFrames * 0.6);
  const t_blackOutDuration = Math.max(1, Math.min(Math.round(fps * 0.5), Math.round(durationInFrames * 0.05)));
  const t_blackScreenHold = Math.max(1, Math.min(fps, Math.round(durationInFrames * 0.1))); // Approx 1s hold
  
  // Phase 3: Centered Gauge Appearance
  const t_gaugeCardStart = t_blackOutStart + t_blackOutDuration + t_blackScreenHold;
  const t_gaugeDrawStart = t_gaugeCardStart + Math.max(1, Math.round(fps * 0.2));
  const t_gaugeDrawEnd = Math.min(durationInFrames, t_gaugeDrawStart + Math.max(1, Math.round(fps * 1.5)));
  const t_statsInStart = t_gaugeCardStart + Math.max(1, Math.round(fps * 0.5));

  const totalTasks = tasks.length;

  // Phase 1 Interpolations
  const topOpacity = interpolate(frame, [t_topFadeStart, t_topFadeStart + fadeDur], [0, 1], { extrapolateRight: "clamp" });
  
  const taskCardOpacity = interpolate(frame, [t_taskCardStart, t_taskCardStart + fadeDur], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const taskCardY = spring({ frame: frame - t_taskCardStart, fps, config: { damping: 14 } });
  const taskCardTransform = `translateY(${interpolate(taskCardY, [0, 1], [40, 0])}px)`;

  const overallProgress = interpolate(frame, [t_taskProgressStart, t_taskProgressEnd], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const activeTaskIndex = Math.min(totalTasks, Math.floor(overallProgress * totalTasks));
  const timerValueStr = (overallProgress * timerMaxSeconds).toFixed(1);

  // Phase 2 Interpolations
  const blackOverlayOpacity = interpolate(
    frame,
    [t_blackOutStart, t_blackOutStart + t_blackOutDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Phase 3 Interpolations
  const gaugeCardOpacity = interpolate(frame, [t_gaugeCardStart, t_gaugeCardStart + fadeDur], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const gaugeCardY = spring({ frame: frame - t_gaugeCardStart, fps, config: { damping: 14 } });
  const gaugeCardTransform = `translate(-50%, calc(-50% + ${interpolate(gaugeCardY, [0, 1], [40, 0])}px))`;

  const gaugeProgress = interpolate(frame, [t_gaugeDrawStart, t_gaugeDrawEnd], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.bezier(0.2, 0.8, 0.2, 1) });
  // Natively scaled SVG path logic (1.5x of original radius 140 -> 210)
  const gaugePathLength = 659.73; // Math.PI * 210
  const strokeDashoffset = gaugePathLength - (gaugeProgress * gaugePathLength);

  const statsOpacity = interpolate(frame, [t_statsInStart, t_statsInStart + fadeDur], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const statsScale = spring({ frame: frame - t_statsInStart, fps, config: { damping: 12 } });
  const statsY = interpolate(statsOpacity, [0, 1], [15, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: containerBg, fontFamily: interFamily, alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
      <div style={{ width: 1920, height: 1080, transform: `scale(${s})`, position: "relative" }}>
        
        {/* Background Ambient Glow */}
        <div style={{
          position: "absolute",
          top: "60%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: 800,
          height: 500,
          backgroundColor: "#2f81f7",
          filter: "blur(140px)",
          opacity: 0.08,
          borderRadius: "50%",
          zIndex: 0,
          transition: "none"
        }} />

        {/* Phase 1: Content Flow Container */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "100%", zIndex: 1, position: "relative" }}>
          
          {/* Top Section */}
          <div style={{ opacity: topOpacity, display: "flex", flexDirection: "column", alignItems: "center", marginBottom: 48, transition: "none" }}>
            <div style={{ display: "flex", gap: 12, justifyContent: "center", marginBottom: 24 }}>
              {Array.from({ length: 6 }).map((_, i) => {
                const wave = interpolate(
                  ((frame * 1.5) - i * 10) % 60,
                  [0, 15, 30],
                  [0.3, 1, 0.3],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                );
                return (
                  <div key={i} style={{ width: 12, height: 12, borderRadius: 6, backgroundColor: "#2f81f7", opacity: wave, transition: "none" }} />
                );
              })}
            </div>
            <h1 style={{ fontSize: 36, fontWeight: 600, color: "#ffffff", margin: 0, marginBottom: 16, textAlign: "center", transition: "none" }}>
              {mainTitle}
            </h1>
            <p style={{ fontSize: 22, color: "#7d8590", margin: 0, textAlign: "center", maxWidth: "70%", lineHeight: 1.5, transition: "none" }}>
              {subTitle}
            </p>
          </div>

          {/* Tasks Card */}
          <div style={{
            width: 760,
            backgroundColor: "#161b22",
            border: "1px solid #30363d",
            borderRadius: 16,
            padding: 32,
            boxShadow: "0 24px 48px rgba(0,0,0,0.4)",
            opacity: taskCardOpacity,
            transform: taskCardTransform,
            marginBottom: 48,
            transition: "none"
          }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16, transition: "none" }}>
              <div style={{ fontSize: 20, color: "#e6edf3", fontWeight: 600 }}>{tasksCardHeader}</div>
              <div style={{ fontSize: 18, color: "#7d8590", fontFamily: robotoMonoFamily }}>{timerValueStr}s</div>
            </div>
            
            <div style={{ width: "100%", height: 4, backgroundColor: "#30363d", borderRadius: 2, marginBottom: 24, overflow: "hidden", transition: "none" }}>
              <div style={{ width: `${overallProgress * 100}%`, height: "100%", backgroundColor: "#2f81f7", borderRadius: 2, transition: "none" }} />
            </div>
            
            <div style={{ display: "flex", flexDirection: "column", gap: 14, transition: "none" }}>
              {tasks.map((task, idx) => {
                const isDone = idx < activeTaskIndex;
                const isActive = idx === activeTaskIndex && overallProgress < 1;

                const dotColor = isActive ? "#2f81f7" : isDone ? "#3fb950" : "#30363d";
                const textColor = isActive ? "#e6edf3" : isDone ? "#7d8590" : "#484f58";

                return (
                  <div key={idx} style={{ display: "flex", alignItems: "center", gap: 14, transition: "none" }}>
                    <div style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: dotColor, flexShrink: 0, transition: "none" }} />
                    <div style={{ color: textColor, fontSize: 18, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", transition: "none" }}>
                      {task}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        {/* Phase 2: Blackout Overlay */}
        <div style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: "#000000",
          opacity: blackOverlayOpacity,
          zIndex: 10,
          transition: "none"
        }} />

        {/* Phase 3: Centered & Enlarged Gauge Card */}
        <div style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 750, // 1.5x of original 500
          backgroundColor: "#161b22",
          border: "1px solid #30363d",
          borderRadius: 24,
          padding: 60,
          boxShadow: "0 36px 72px rgba(0,0,0,0.8)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          opacity: gaugeCardOpacity,
          transform: gaugeCardTransform,
          zIndex: 20,
          transition: "none"
        }}>
          <div style={{ fontSize: 21, color: "#7d8590", fontWeight: 600, letterSpacing: 3.75, marginBottom: 48, transition: "none" }}>
            {timeToValueHeader}
          </div>
          
          <div style={{ position: "relative", width: 540, height: 270, transition: "none" }}>
            <svg width="540" height="270" viewBox="0 0 540 270" style={{ overflow: "visible" }}>
              <defs>
                <linearGradient id="gaugeGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                  <stop offset="0%" stopColor="#3fb950" />
                  <stop offset="50%" stopColor="#d29922" />
                  <stop offset="100%" stopColor="#2f81f7" />
                </linearGradient>
              </defs>
              <path d="M 60 255 A 210 210 0 0 1 480 255" fill="none" stroke="#30363d" strokeWidth="24" strokeLinecap="round" style={{ transition: "none" }} />
              <path 
                d="M 60 255 A 210 210 0 0 1 480 255" 
                fill="none" 
                stroke="url(#gaugeGradient)" 
                strokeWidth="24" 
                strokeLinecap="round" 
                strokeDasharray={gaugePathLength}
                strokeDashoffset={strokeDashoffset}
                style={{ transition: "none" }}
              />
            </svg>
            <div style={{ 
              position: "absolute", bottom: -15, left: 0, right: 0, textAlign: "center", 
              fontSize: 108, fontWeight: 700, color: "#ffffff", letterSpacing: "-0.02em",
              opacity: statsOpacity, transform: `scale(${statsScale})`,
              transition: "none"
            }}>
              {gaugeTime}
            </div>
          </div>
          
          <div style={{ 
            display: "flex", alignItems: "center", gap: 21, marginTop: 36,
            opacity: statsOpacity, transform: `translateY(${statsY}px)`,
            transition: "none"
          }}>
            <span style={{ color: "#7d8590", textDecoration: "line-through", fontSize: 24, transition: "none" }}>{oldTimeText}</span>
            <span style={{ color: "#7d8590", fontSize: 24, transition: "none" }}>→</span>
            <span style={{ color: "#3fb950", fontSize: 24, fontWeight: "bold", transition: "none" }}>{newTimeText}</span>
            <div style={{ border: "1px solid rgba(47, 129, 247, 0.4)", backgroundColor: "rgba(47, 129, 247, 0.1)", borderRadius: 9, padding: "6px 15px", color: "#2f81f7", fontSize: 21, fontWeight: 700, transition: "none" }}>
              {multiplierText}
            </div>
          </div>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default ValuationAnimation;